from datetime import datetime
import pytz
import re
from faker import Faker

def task_func(epoch_milliseconds, seed=0, timezones=["UTC"]):
    fake = Faker()
    fake.seed_instance(seed)

    if isinstance(timezones, str):
        timezones = [timezones]

    local_timezone = datetime.now().astimezone().tzinfo or pytz.UTC
    event_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000.0, tz=local_timezone)

    def is_valid_timezone(tz_name):
        if tz_name in pytz.all_timezones:
            return True

        match = re.fullmatch(r"UTC([+-])(\d{2}):(\d{2})", tz_name)
        if not match:
            return False

        hours = int(match.group(2))
        minutes = int(match.group(3))
        return hours <= 23 and minutes <= 59

    valid_timezones = []
    if timezones:
        for tz in timezones:
            if tz is None:
                continue
            tz_str = str(tz).strip()
            if is_valid_timezone(tz_str):
                valid_timezones.append(tz_str)

    selected_timezone = "UTC" if not valid_timezones else fake.random_element(elements=valid_timezones)
    event_name = fake.catch_phrase()

    return {
        event_name: [
            {
                "date": event_datetime.strftime("%Y-%m-%d"),
                "time": event_datetime.strftime("%H:%M:%S"),
                "timezone": selected_timezone,
            }
        ]
    }
